from itertools import permutations, combinations

def time_str(minutes):
    # minutes from midnight
    h = minutes // 60
    m = minutes % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

# Directed travel times in minutes
dist = {
    "Sunset District": {
        "Embarcadero": 31,
        "Presidio": 16,
        "Mission District": 24,
    },
    "Embarcadero": {
        "Sunset District": 30,
        "Presidio": 20,
        "Mission District": 20,
    },
    "Presidio": {
        "Sunset District": 15,
        "Embarcadero": 20,
        "Mission District": 26,
    },
    "Mission District": {
        "Sunset District": 24,
        "Embarcadero": 19,
        "Presidio": 25,
    }
}

# Friend availability and minimum meeting duration
friends_all = [
    {"name": "John", "loc": "Embarcadero", "start": 13*60 + 15, "end": 16*60, "min": 90},
    {"name": "Paul", "loc": "Presidio", "start": 9*60, "end": 13*60, "min": 120},
    {"name": "Daniel", "loc": "Mission District", "start": 15*60 + 45, "end": 18*60, "min": 90},
]

START_LOC = "Sunset District"
START_TIME = 9*60  # 9:00AM

def plan_for_order(order):
    best = None  # (sum_meet, sum_wait, finish_time, steps)
    # Depth-first search over candidate departure times at each friend
    def dfs(i, cur_loc, cur_time, steps, sum_meet, sum_wait):
        nonlocal best
        if i == len(order):
            # finished this order
            candidate = (sum_meet, sum_wait, cur_time, steps)
            if best is None:
                best = candidate
            else:
                # prefer more meeting time, then less wait, then earlier finish
                if (candidate[0] > best[0] or
                    (candidate[0] == best[0] and candidate[1] < best[1]) or
                    (candidate[0] == best[0] and candidate[1] == best[1] and candidate[2] < best[2])):
                    best = candidate
            return

        f = order[i]
        # Travel
        t_travel = dist[cur_loc][f["loc"]]
        arrival = cur_time + t_travel
        local_steps = steps + [f"You travel to {f['loc']} in {t_travel} minutes and arrive at {time_str(arrival)}."]

        # Wait if early
        wait = 0
        start_meet = arrival
        if start_meet < f["start"]):
            wait = f["start"] - start_meet
            start_meet = f["start"]
            local_steps += [f"You wait until {time_str(start_meet)}."]

        # Feasibility
        min_end = start_meet + f["min"]
        if min_end > f["end"]:
            return  # infeasible branch

        # Candidate meeting end times
        ends = set()
        ends.add(min_end)

        if i < len(order) - 1:
            nxt = order[i+1]
            t_to_next = dist[f["loc"]][nxt["loc"]]
            # try to align arrival with next start to minimize waiting there
            target_depart = nxt["start"] - t_to_next
            if min_end <= target_depart <= f["end"]:
                ends.add(target_depart)
            # latest depart that still allows minimum with the next friend
            latest_depart = nxt["end"] - nxt["min"] - t_to_next
            # we cannot leave after f['end']
            latest_depart = min(latest_depart, f["end"])
            if latest_depart >= min_end:
                ends.add(latest_depart)
        else:
            # Last friend: also consider staying until window end to maximize meeting time
            ends.add(f["end"])

        for e in sorted(ends):
            meet_dur = e - start_meet
            step_meet = f"You meet {f['name']} for {meet_dur} minutes from {time_str(start_meet)} to {time_str(e)}."
            dfs(i+1, f["loc"], e, local_steps + [step_meet], sum_meet + meet_dur, sum_wait + wait)

    # Initialize with start message
    init_steps = [f"You start at {START_LOC} at {time_str(START_TIME)}."]
    dfs(0, START_LOC, START_TIME, init_steps, 0, 0)
    return best  # may be None if infeasible

def rank_key(result, count):
    # result: (sum_meet, sum_wait, finish_time, steps)
    sum_meet, sum_wait, finish_time, _ = result
    # Higher count, then higher meeting time, then lower waiting, then earlier finish
    return (count, sum_meet, -sum_wait, -finish_time)

def main():
    best_global = None  # (count, sum_meet, sum_wait, finish_time, steps)
    # consider all non-empty subsets, but we will keep the globally best
    n = len(friends_all)
    for r in range(n, 0, -1):
        for subset in combinations(friends_all, r):
            for order in permutations(subset):
                res = plan_for_order(order)
                if res is None:
                    continue
                sum_meet, sum_wait, finish_time, steps = res
                candidate = (r, sum_meet, sum_wait, finish_time, steps)
                if best_global is None:
                    best_global = candidate
                else:
                    # Compare using the ranking rule
                    bc = best_global
                    # First by count
                    if candidate[0] > bc[0]:
                        best_global = candidate
                    elif candidate[0] == bc[0]:
                        # Then by total meeting time
                        if candidate[1] > bc[1]:
                            best_global = candidate
                        elif candidate[1] == bc[1]:
                            # Then by less waiting
                            if candidate[2] < bc[2]:
                                best_global = candidate
                            elif candidate[2] == bc[2]:
                                # Then by earlier finish
                                if candidate[3] < bc[3]:
                                    best_global = candidate
        # Early stop if we found a schedule meeting all friends
        if best_global and best_global[0] == n:
            break

    if best_global is None:
        itinerary = [f"You start at {START_LOC} at {time_str(START_TIME)}.", "No feasible schedule found."]
    else:
        itinerary = best_global[4]

    print(itinerary)

if __name__ == "__main__":
    main()

from itertools import permutations

# Time helpers
def to_minutes(h, m):
    return h * 60 + m

def fmt_time(minutes):
    # minutes from midnight to h:MMAM/PM
    h = (minutes // 60) % 24
    m = minutes % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

# Travel times (directed, minutes)
travel = {
    "Alamo Square": {
        "Bayview": 16, "Union Square": 14, "Financial District": 17, "Richmond District": 12
    },
    "Bayview": {
        "Alamo Square": 16, "Union Square": 17, "Financial District": 19, "Richmond District": 25
    },
    "Union Square": {
        "Alamo Square": 15, "Bayview": 15, "Financial District": 9, "Richmond District": 20
    },
    "Financial District": {
        "Alamo Square": 17, "Bayview": 19, "Union Square": 9, "Richmond District": 21
    },
    "Richmond District": {
        "Alamo Square": 13, "Bayview": 26, "Union Square": 21, "Financial District": 22
    }
}

# Friends: name -> location, availability window [start,end], duration (min)
friends = {
    "Anthony": {
        "location": "Bayview",
        "start": to_minutes(14, 0),   # 2:00PM
        "end": to_minutes(18, 45),    # 6:45PM
        "duration": 45
    },
    "Elizabeth": {
        "location": "Union Square",
        "start": to_minutes(13, 15),  # 1:15PM
        "end": to_minutes(16, 0),     # 4:00PM
        "duration": 75
    },
    "Steven": {
        "location": "Financial District",
        "start": to_minutes(16, 30),  # 4:30PM
        "end": to_minutes(18, 45),    # 6:45PM
        "duration": 60
    },
    "Karen": {
        "location": "Richmond District",
        "start": to_minutes(7, 45),   # 7:45AM
        "end": to_minutes(22, 0),     # 10:00PM
        "duration": 90
    }
}

start_location = "Alamo Square"
start_time = to_minutes(9, 0)  # 9:00AM

def simulate(order):
    curr_loc = start_location
    curr_time = start_time
    steps = [f"You start at {start_location} at {fmt_time(start_time)}."]
    met_count = 0
    total_wait = 0
    total_travel = 0

    for name in order:
        f = friends[name]
        dest = f["location"]
        # If no direct travel (shouldn't happen), skip
        if curr_loc not in travel or dest not in travel[curr_loc]:
            continue
        t_travel = travel[curr_loc][dest]
        arrival = curr_time + t_travel

        # Compute earliest feasible start
        meet_start = max(arrival, f["start"])
        meet_end = meet_start + f["duration"]
        if meet_end > f["end"]:
            # Not feasible to meet this friend from current state; skip
            continue

        # Commit travel
        steps.append(f"You travel to {dest} in {t_travel} minutes and arrive at {fmt_time(arrival)}.")
        total_travel += t_travel
        # Waiting if arriving before feasible start
        if arrival < meet_start:
            steps.append(f"You wait until {fmt_time(meet_start)}.")
            total_wait += (meet_start - arrival)

        # Meeting
        steps.append(f"You meet {name} for {f['duration']} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        met_count += 1
        curr_loc = dest
        curr_time = meet_end

    finish_time = curr_time
    return {
        "steps": steps,
        "met": met_count,
        "finish": finish_time,
        "wait": total_wait,
        "travel": total_travel
    }

# Evaluate all permutations and pick the best plan
best = None
for order in permutations(friends.keys()):
    result = simulate(order)
    if best is None:
        best = (result, order)
    else:
        r, _ = result, order
        b, _ = best
        # Primary: maximize number met
        if r["met"] > b["met"]:
            best = (result, order)
        elif r["met"] == b["met"]:
            # Secondary: minimize finish time
            if r["finish"] < b["finish"]:
                best = (result, order)
            elif r["finish"] == b["finish"]:
                # Tertiary: minimize total waiting, then travel
                if r["wait"] < b["wait"] or (r["wait"] == b["wait"] and r["travel"] < b["travel"]):
                    best = (result, order)

best_result, best_order = best

# Print the chosen schedule list (as per the requested example format)
print(best_result["steps"])

from itertools import permutations, chain

def parse_time(s):
    # returns minutes since midnight
    s = s.strip().upper()
    if s.endswith("AM") or s.endswith("PM"):
        ampm = s[-2:]
        hhmm = s[:-2]
    else:
        # assume 24h
        ampm = None
        hhmm = s
    hh, mm = hhmm.split(":")
    h, m = int(hh), int(mm)
    if ampm == "AM":
        if h == 12:  # 12:xx AM is 00:xx
            h = 0
    elif ampm == "PM":
        if h != 12:
            h += 12
    return h * 60 + m

def minutes_to_ampm(t):
    # t is minutes since midnight
    h = (t // 60) % 24
    m = t % 60
    ampm = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ampm}"

