        "Russian Hill": 13,
    },
}

# Friends with windows and minimum durations
friends = {
    "Brian": {
        "loc": "Marina District",
        "start": parse_time("4:30PM"),
        "end": parse_time("7:45PM"),
        "dur": 15
    },
    "Laura": {
        "loc": "Alamo Square",
        "start": parse_time("8:15AM"),
        "end": parse_time("2:00PM"),
        "dur": 75
    },
    "Elizabeth": {
        "loc": "Sunset District",
        "start": parse_time("12:15PM"),
        "end": parse_time("8:00PM"),
        "dur": 45
    },
    "Lisa": {
        "loc": "Russian Hill",
        "start": parse_time("8:30AM"),
        "end": parse_time("7:45PM"),
        "dur": 30
    },
    "Margaret": {
        "loc": "Union Square",
        "start": parse_time("7:45PM"),
        "end": parse_time("10:00PM"),
        "dur": 75
    },
}

def simulate(order, start_loc, start_time):
    steps = []
    steps.append(f"You start at {start_loc} at {minutes_to_ampm(start_time)}.")
    cur_loc = start_loc
    t = start_time
    total_wait = 0
    total_travel = 0

    for name in order:
        f = friends[name]
        # travel
        tt = travel[cur_loc][f["loc"]]
        t_arr = t + tt
        total_travel += tt
        steps.append(f"You travel to {f['loc']} in {tt} minutes and arrive at {minutes_to_ampm(t_arr)}.")

        # earliest feasible start
        start_meet = max(t_arr, f["start"])
        if start_meet > t_arr:
            total_wait += (start_meet - t_arr)
            steps.append(f"You wait until {minutes_to_ampm(start_meet)}.")

        end_meet = start_meet + f["dur"]
        if end_meet > f["end"]:
            return None  # infeasible

        steps.append(f"You meet {name} for {f['dur']} minutes from {minutes_to_ampm(start_meet)} to {minutes_to_ampm(end_meet)}.")
        # update state
        t = end_meet
        cur_loc = f["loc"]

    result = {
        "steps": steps,
        "met": len(order),
        "wait": total_wait,
        "travel": total_travel,
        "finish": t
    }
    return result

def all_subsets(iterable):
    items = list(iterable)
    # all non-empty subsets
    return chain.from_iterable(permutations(items, r) for r in range(len(items), 0, -1))

def solve():
    start_loc = "The Castro"
    start_time = parse_time("9:00AM")

    best = None
    # Evaluate all permutations of all subset sizes from largest to smallest
    for order in all_subsets(list(friends.keys())):
        res = simulate(order, start_loc, start_time)
        if res is None:
            continue
        if best is None:
            best = res
        else:
            # primary: maximize number met
            if res["met"] > best["met"]:
                best = res
            elif res["met"] == best["met"]:
                # secondary: minimize total waiting time
                if res["wait"] < best["wait"]:
                    best = res
                elif res["wait"] == best["wait"]:
                    # tertiary: minimize travel time
                    if res["travel"] < best["travel"]:
                        best = res
                    elif res["travel"] == best["travel"]:
                        # quaternary: earliest finish
                        if res["finish"] < best["finish"]:
                            best = res

    return best

if __name__ == "__main__":
    plan = solve()
    # Print the chosen plan steps as a list of strings, matching the requested format
    print(plan["steps"])

from itertools import permutations, combinations

# Helper functions
def to_minutes(h, m):
    return h * 60 + m

def parse_time(timestr):
    # expects like "9:00AM", "3:15PM"
    timestr = timestr.strip().upper()
    ampm = timestr[-2:]
    hhmm = timestr[:-2]
    h, m = map(int, hhmm.split(":"))
    if ampm == "AM":
        if h == 12:
            h = 0
    else:  # PM
        if h != 12:
            h += 12
    return h * 60 + m

def minutes_to_ampm(t):
    t = t % (24*60)
    h = t // 60
    m = t % 60
    ampm = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ampm}"

# Travel times (directed, minutes)
travel = {
    "Presidio": {
        "Pacific Heights": 11, "Richmond District": 7, "Union Square": 22, "Mission District": 26, "Russian Hill": 14
    },
    "Pacific Heights": {
        "Presidio": 11, "Richmond District": 12, "Union Square": 12, "Mission District": 15, "Russian Hill": 7
    },
    "Richmond District": {
        "Presidio": 7, "Pacific Heights": 10, "Union Square": 21, "Mission District": 20, "Russian Hill": 13
    },
    "Union Square": {
        "Presidio": 24, "Pacific Heights": 15, "Richmond District": 20, "Mission District": 14, "Russian Hill": 13
    },
    "Mission District": {
        "Presidio": 25, "Pacific Heights": 16, "Richmond District": 20, "Union Square": 15, "Russian Hill": 15
    },
    "Russian Hill": {
        "Presidio": 14, "Pacific Heights": 7, "Richmond District": 14, "Union Square": 11, "Mission District": 16
    }
}

# Friends: location, availability window, required duration (minutes)
friends = {
    "Emily": {
        "loc": "Pacific Heights",
        "start": parse_time("3:00PM"),
        "end": parse_time("6:00PM"),
        "dur": 90
    },
    "Mary": {
        "loc": "Richmond District",
        "start": parse_time("10:45AM"),
        "end": parse_time("8:30PM"),
        "dur": 60
    },
    "Mark": {
        "loc": "Union Square",
        "start": parse_time("12:15PM"),
        "end": parse_time("10:00PM"),
        "dur": 75
    },
    "Ronald": {
        "loc": "Mission District",
        "start": parse_time("10:00AM"),
        "end": parse_time("6:30PM"),
        "dur": 105
    },
    "Joshua": {
        "loc": "Russian Hill",
        "start": parse_time("9:30PM"),
        "end": parse_time("10:30PM"),
        "dur": 30
    }
}

start_loc = "Presidio"
start_time = parse_time("9:00AM")

def evaluate_order(order):
    steps = []
    curr_loc = start_loc
    curr_time = start_time

    steps.append(f"You start at {curr_loc} at {minutes_to_ampm(curr_time)}.")

    total_wait = 0
    total_travel = 0
    meetings_done = []

    for name in order:
        info = friends[name]
        next_loc = info["loc"]

        # Travel
        travel_time = travel[curr_loc][next_loc]
        total_travel += travel_time
        arrive_time = curr_time + travel_time
        steps.append(f"You travel to {next_loc} in {travel_time} minutes and arrive at {minutes_to_ampm(arrive_time)}.")

        # Wait if early
        start_meet = max(arrive_time, info["start"])
        wait_time = max(0, info["start"] - arrive_time)
        if wait_time > 0:
            steps.append(f"You wait until {minutes_to_ampm(start_meet)}.")
            total_wait += wait_time

        end_meet = start_meet + info["dur"]
        if end_meet > info["end"]:
            # infeasible
            return None

        steps.append(f"You meet {name} for {info['dur']} minutes from {minutes_to_ampm(start_meet)} to {minutes_to_ampm(end_meet)}.")
        meetings_done.append(name)

        # Update state
        curr_loc = next_loc
        curr_time = end_meet

    return {
        "steps": steps,
        "count": len(meetings_done),
        "total_wait": total_wait,
        "finish_time": curr_time,
        "total_travel": total_travel,
        "order": order
    }

# Search best schedule: maximize number of friends, then minimize total waiting, then earliest finish, then least travel
names = list(friends.keys())
best = None

for k in range(len(names), 0, -1):
    found_for_k = []
    for subset in combinations(names, k):
        for perm in permutations(subset):
            res = evaluate_order(perm)
            if res is not None:
                found_for_k.append(res)
    if found_for_k:
        # Select best under tie-breakers
        found_for_k.sort(key=lambda r: (r["total_wait"], r["finish_time"], r["total_travel"]))
        best = found_for_k[0]
        break

# Output
if best is None:
    schedule = ["No feasible schedule found."]
else:
    schedule = best["steps"]

print(schedule)

from itertools import permutations, combinations

# Time formatting helpers
def fmt_time(t):
    h = (t // 60) % 24
    m = t % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

# Travel times (directed, minutes)
T = {
    "Pacific Heights": {
        "Bayview": 22, "Russian Hill": 7, "Financial District": 13,
