    }
}

# Friend definitions
def t(h, m):  # minutes since midnight
    return h * 60 + m

friends = [
    {"name": "Joseph",  "loc": "Bayview",           "start": t(12,15), "end": t(20,15), "dur": 45},
    {"name": "Andrew",  "loc": "Russian Hill",      "start": t(15,45), "end": t(20,45), "dur": 60},
    {"name": "Carol",   "loc": "Financial District","start": t(17,30), "end": t(20,45), "dur": 30},
    {"name": "David",   "loc": "The Castro",        "start": t(7,30),  "end": t(13,30), "dur": 45},
    {"name": "Rebecca", "loc": "Presidio",          "start": t(11,0),  "end": t(21,15), "dur": 105},
    {"name": "Laura",   "loc": "Alamo Square",      "start": t(12,30), "end": t(21,30), "dur": 75},
]

start_loc = "Pacific Heights"
start_time = t(9, 0)

def simulate(order):
    time = start_time
    loc = start_loc
    plan = [f"You start at {start_loc} at {fmt_time(start_time)}."]
    total_travel = 0

    for f in order:
        travel = T[loc][f["loc"]]
        time += travel
        total_travel += travel
        plan.append(f"You travel to {f['loc']} in {travel} minutes and arrive at {fmt_time(time)}.")
        meet_start = max(time, f["start"])
        if meet_start > time:
            plan.append(f"You wait until {fmt_time(meet_start)}.")
        meet_end = meet_start + f["dur"]
        if meet_end > f["end"]:
            return None  # infeasible
        plan.append(f"You meet {f['name']} for {f['dur']} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        time = meet_end
        loc = f["loc"]

    return {
        "plan": plan,
        "finish_time": time,
        "travel": total_travel,
        "count": len(order)
    }

# Search best schedule: maximize count, then minimize finish time, then minimize travel
best = None
n = len(friends)

for k in range(n, 0, -1):
    found_any = False
    # All combinations of size k
    for combo in combinations(friends, k):
        for order in permutations(combo):
            result = simulate(order)
            if result is None:
                continue
            found_any = True
            if best is None:
                best = result
            else:
                # Better if more friends (equal by design for fixed k), then earlier finish, then less travel
                if result["count"] > best["count"]:
                    best = result
                elif result["count"] == best["count"]:
                    if result["finish_time"] < best["finish_time"]:
                        best = result
                    elif result["finish_time"] == best["finish_time"] and result["travel"] < best["travel"]:
                        best = result
    if found_any:
        break

# Output
if best is None:
    print(["No feasible schedule."])
else:
    print(best["plan"])

