import itertools

def tmin(h, m=0, ampm="AM"):
    # returns minutes from midnight
    h = int(h); m = int(m)
    ampm = ampm.upper()
    if ampm == "AM":
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return h * 60 + m

def fmt_time(minutes):
    # format minutes from midnight to "H:MMAM/PM"
    minutes = int(minutes)
    h24 = (minutes // 60) % 24
    m = minutes % 60
    ampm = "AM" if h24 < 12 else "PM"
    h12 = h24 % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ampm}"

# Directed travel times (minutes)
