    },
    "Presidio": {
        "Alamo Square": 18, "Nob Hill": 18, "The Castro": 21, "North Beach": 18, "Richmond District": 7, "Bayview": 31
    }
}

# Friends: name -> dict with location, window start/end, min duration
friends = {
    "Melissa": {"loc": "Nob Hill", "start": tmin(9,15,"AM"), "end": tmin(1,30,"PM"), "min": 60},
    "George": {"loc": "The Castro", "start": tmin(4,0,"PM"), "end": tmin(9,45,"PM"), "min": 90},
    "Daniel": {"loc": "North Beach", "start": tmin(6,15,"PM"), "end": tmin(9,15,"PM"), "min": 120},
    "Michelle": {"loc": "Richmond District", "start": tmin(11,30,"AM"), "end": tmin(6,45,"PM"), "min": 45},
    "Jessica": {"loc": "Bayview", "start": tmin(7,45,"PM"), "end": tmin(9,30,"PM"), "min": 90},
    "Paul": {"loc": "Presidio", "start": tmin(9,0,"AM"), "end": tmin(8,0,"PM"), "min": 60},
}

start_loc = "Alamo Square"
start_time = tmin(9,0,"AM")

def simulate(order):
    # Simulate visiting friends in given order; return (feasible, lines, count, wait_total, finish_time)
    curr_loc = start_loc
    curr_time = start_time
    lines = [f"You start at {start_loc} at {fmt_time(start_time)}."]
    total_wait = 0
    met_count = 0

    for name in order:
        loc = friends[name]["loc"]
        # travel time
        if curr_loc == loc:
            travel = 0
        else:
            if curr_loc not in T or loc not in T[curr_loc]:
                return (False, [], 0, float('inf'), float('inf'))
            travel = T[curr_loc][loc]
        arrive = curr_time + travel
        lines.append(f"You travel to {loc} in {travel} minutes and arrive at {fmt_time(arrive)}.")
        # schedule meeting
        start_win = friends[name]["start"]
        end_win = friends[name]["end"]
        min_dur = friends[name]["min"]
        meet_start = max(arrive, start_win)
        if meet_start > arrive:
            lines.append(f"You wait until {fmt_time(meet_start)}.")
            total_wait += (meet_start - arrive)
        meet_end = meet_start + min_dur
        if meet_end > end_win:
            return (False, [], 0, float('inf'), float('inf'))
        lines.append(f"You meet {name} for {min_dur} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        curr_loc = loc
        curr_time = meet_end
        met_count += 1

    return (True, lines, met_count, total_wait, curr_time)

# Search all subsets and sequences
all_names = list(friends.keys())
best = None  # tuple (met_count, total_wait, finish_time, lines)
for k in range(len(all_names), 0, -1):
    found_any = []
    for subset in itertools.combinations(all_names, k):
        for order in itertools.permutations(subset):
            feasible, lines, count, wait_total, finish_time = simulate(order)
            if feasible:
                found_any.append((count, wait_total, finish_time, lines))
    if found_any:
        # choose best by max count (same for all), min wait, then earliest finish
        found_any.sort(key=lambda x: (-x[0], x[1], x[2]))
        best = found_any[0]
        break

# Output
plan_lines = best[3] if best else ["No feasible schedule found."]
print(plan_lines)
