from dataclasses import dataclass
from typing import Dict, List, Tuple, Set

# Time utilities
def to_minutes(hhmm_ampm: str) -> int:
    # Not used here since we hardcode minutes directly, but kept for generality.
    import re
    m = re.match(r'(\d+):(\d+)(AM|PM)', hhmm_ampm.strip().upper())
    if not m:
        raise ValueError("Bad time format")
    h, mi, ap = int(m.group(1)), int(m.group(2)), m.group(3)
    if h == 12:
        h = 0
    mins = h * 60 + mi
    if ap == 'PM':
        mins += 12 * 60
    return mins

def fmt_time(mins: int) -> str:
    mins = int(mins)
    h = (mins // 60) % 24
    m = mins % 60
    ap = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ap}"

