    'count': -1,
    'wait': 10**9,
    'end_time': 10**9,
    'steps': [],
    'visited': set()
}

def search(curr_loc: str, curr_time: int, visited: Set[Friend], steps: List[str], total_wait: int):
    global best_result

    # Check if this leaf is better
    if True:
        count = len(visited)
        # Update best if better per tie-breakers
        better = False
        if count > best_result['count']:
            better = True
        elif count == best_result['count']:
            if total_wait < best_result['wait']:
                better = True
            elif total_wait == best_result['wait'] and curr_time < best_result['end_time']:
                better = True
        if better:
            best_result = {
                'count': count,
                'wait': total_wait,
                'end_time': curr_time,
                'steps': steps[:],
                'visited': set(v.name for v in visited)
            }

    # Try to extend with any feasible next friend
    for f in friends:
        if f in visited:
            continue
        # Travel time (directed)
        if curr_loc not in dist or f.loc not in dist[curr_loc]:
            continue
        travel = dist[curr_loc][f.loc]
        arrival = curr_time + travel
        start = max(arrival, f.start)
        end = start + f.dur
        if end <= f.end:
            new_steps = steps[:]
            # Add travel step
            new_steps.append(f"You travel to {f.loc} in {travel} minutes and arrive at {fmt_time(arrival)}.")
            # Add wait step if any
            wait = max(0, start - arrival)
            if wait > 0:
                new_steps.append(f"You wait until {fmt_time(start)}.")
            # Meeting step
            new_steps.append(f"You meet {f.name} for {f.dur} minutes from {fmt_time(start)} to {fmt_time(end)}.")
            visited.add(f)
            search(f.loc, end, visited, new_steps, total_wait + wait)
            visited.remove(f)

