def dfs(current_loc: str, current_time: int, remaining: Tuple[str, ...],
        memo: Dict = None) -> Tuple[int, int, int, List[Tuple[str, int, int]]]:
    """
    Returns (count_met, total_meeting_minutes, finish_time, schedule_list)
    schedule_list is list of tuples: (friend_name, meeting_start, meeting_end)
    """
    if memo is None:
        memo = {}
    key = (current_loc, current_time, remaining)
    if key in memo:
        return memo[key]

    best = (0, 0, current_time, [])  # if no more meetings
    for name in remaining:
        info = friend_info[name]
        travel = dist[current_loc][info['loc']]
        arrival = current_time + travel
        earliest_start = max(arrival, info['start'])
        latest_start = info['end'] - info['dur']
        if earliest_start <= latest_start:
            meet_start = earliest_start
            meet_end = meet_start + info['dur']
            remaining_next = tuple(n for n in remaining if n != name)
            sub = dfs(info['loc'], meet_end, remaining_next, memo)
            cand = (1 + sub[0], info['dur'] + sub[1], sub[2], [(name, meet_start, meet_end)] + sub[3])
            # Compare: max count, then max total minutes, then min finish time
            if (cand[0] > best[0]) or \
               (cand[0] == best[0] and cand[1] > best[1]) or \
               (cand[0] == best[0] and cand[1] == best[1] and cand[2] < best[2]):
                best = cand

    memo[key] = best
    return best

def build_schedule_text(schedule_list: List[Tuple[str, int, int]]) -> List[str]:
    lines = []
    start_loc = 'Golden Gate Park'
    start_time = 9*60  # 9:00 AM
    lines.append(f"You start at {start_loc} at {fmt_time(start_time)}.")
    prev_loc = start_loc
    prev_time = start_time

    for name, meet_start, meet_end in schedule_list:
        loc = friend_info[name]['loc']
        travel = dist[prev_loc][loc]
        arrival = prev_time + travel
        lines.append(f"You travel to {loc} in {travel} minutes and arrive at {fmt_time(arrival)}.")
        if arrival < meet_start:
            lines.append(f"You wait until {fmt_time(meet_start)}.")
        duration = meet_end - meet_start
        lines.append(f"You meet {name} for {duration} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        prev_loc = loc
        prev_time = meet_end

    return lines

def main():
    start_loc = 'Golden Gate Park'
    start_time = 9*60  # 9:00 AM
    remaining = tuple(friend_names)
    _, _, _, schedule_list = dfs(start_loc, start_time, remaining, memo={})
    schedule_text = build_schedule_text(schedule_list)
    print(schedule_text)

if __name__ == "__main__":
    main()
